-- Migração 37 (cw_prod): categorização automática (chave da origem, escopo da decisão, regras de comerciantes). Já aplicada em produção em 2026-10-24. Cole no SQL Editor e execute.
begin;
-- GENERATED by scripts/gen-migrations.mjs from supabase/templates. Do not edit by hand.
-- Gate 27 (D-061): automatic categorization. Additive.
--  • Recurrence key: the counterparty of a Pix/transfer without the parts that change every time (document numbers,
--    dates, ids), so "PIX ENVIADO 0412 JOAO EXEMPLO 7731" and next month's "PIX ENVIADO 0509 JOAO EXEMPLO 8820" are the
--    same payee. When nothing distinctive is left ("PIX ENVIADO 12345678000190"), the full normalized text is the key.
--  • Rules also match on that key, so a client rule learned from one decision catches the next occurrence.
--  • Decision scope chosen by the client/consultant: only this one, this one and the next ones (recurring), or all.
--  • More global rules for well-known merchants; new subcategory for water and sewage.

insert into cw_prod.transaction_subcategories (code, category_code, label_pt, kind, planning_group, default_recurrence, sort_order)
values ('HOUSING_WATER', 'HOUSING', 'Água e saneamento', 'EXPENSE', 'ESSENTIAL_FIXED', 'RECURRING', 25)
on conflict (code) do nothing;

-- Normalized text without tokens that contain digits.
create function cw_prod_private.merchant_key(p text) returns text
language sql immutable set search_path = '' as $$
  select coalesce(string_agg(w, ' ' order by n), '')
    from regexp_split_to_table(coalesce(p, ''), ' ') with ordinality as x(w, n)
   where w <> '' and w !~ '[0-9]'
$$;

-- Payee key for recurring movements: the digit-free text when it still names someone, else the full normalized text.
create function cw_prod_private.recurrence_key(p_merchant text) returns text
language sql immutable set search_path = '' as $$
  select case when exists (
           select 1 from regexp_split_to_table(cw_prod_private.merchant_key(p_merchant), ' ') w
            where length(w) >= 3 and w not in ('PIX', 'ENVIADO', 'ENVIADA', 'RECEBIDO', 'RECEBIDA', 'ENV', 'REC', 'RECEB', 'TRANSF',
              'TRANSFERENCIA', 'TRANSFER', 'TED', 'DOC', 'TEV', 'TEF', 'PAGAMENTO', 'PAGTO', 'PAG', 'PGTO', 'BOLETO', 'COMPRA',
              'CARTAO', 'DEBITO', 'CREDITO', 'DEB', 'CRED', 'DAS', 'DOS', 'PARA', 'SAQUE', 'DEPOSITO', 'QRCODE', 'CODE', 'CHAVE',
              'CPF', 'CNPJ', 'AGENDADO', 'AGENDAMENTO', 'INTERNET', 'BANKING', 'APP', 'CELULAR', 'ELO', 'VISA', 'MASTERCARD',
              'MASTER', 'SEM', 'DESCRICAO', 'REMETENTE', 'FAVORECIDO', 'CONTA', 'CORRENTE', 'OUTRA', 'OUTRO', 'INSTITUICAO',
              'BANCO', 'TITULARIDADE', 'MESMA', 'NACIONAL', 'INTERNACIONAL', 'ONLINE', 'LINE', 'ELETRONICO', 'ELETRONICA'))
         then cw_prod_private.merchant_key(p_merchant) else p_merchant end
$$;

-- Card descriptors are cut at ~22 characters and often glue words ("SUPERMERCAD", "APPLECOMBILL", "LELESORVETESLTDA"):
-- a CONTAINS rule matches its pattern inside the text with spaces removed. Only long, distinctive patterns (≥ 5 letters).
alter table cw_prod.transaction_rules add column match_mode text not null default 'WORD'
  check (match_mode in ('WORD', 'CONTAINS')),
  add constraint transaction_rules_contains_len check (match_mode = 'WORD' or length(replace(pattern, ' ', '')) >= 5);

-- Same contract as before; a WORD rule now also matches the recurrence key; CONTAINS rules ignore spaces. Client rules first.
create or replace function cw_prod_private.match_rule(p_client uuid, p_merchant text, p_direction text, p_kind text)
returns cw_prod.transaction_rules
language sql stable security definer set search_path = '' as $$
  select r from cw_prod.transaction_rules r
   where r.active and (r.scope = 'GLOBAL' or r.client_id = p_client)
     and r.direction in ('ANY', p_direction) and r.account_kind in ('ANY', p_kind)
     and (case when r.match_mode = 'CONTAINS'
               then replace(p_merchant, ' ', '') like ('%' || replace(r.pattern, ' ', '') || '%')
               else (' ' || p_merchant || ' ') like ('% ' || r.pattern || ' %')
                 or (' ' || cw_prod_private.merchant_key(p_merchant) || ' ') like ('% ' || r.pattern || ' %') end)
   order by (r.scope = 'CLIENT') desc, r.priority desc, length(r.pattern) desc, r.id
   limit 1
$$;

-- Decision with scope:
--   ONE    only this movement;
--   FUTURE this one, the ones of the same payee still waiting for review, and every future import (client rule);
--   ALL    FUTURE plus the ones already classified automatically (manual decisions are never overwritten).
-- Returns how many movements were classified.
create function cw_prod.transaction_classify_scope(p_txn uuid, p_nature text, p_subcategory text, p_scope text)
returns integer
language plpgsql security definer set search_path = '' as $$
declare t cw_prod.transactions; v_key text; v_rule uuid; v_n int; r record;
begin
  if p_scope is null or p_scope not in ('ONE', 'FUTURE', 'ALL') then raise exception 'invalid scope' using errcode = '22023'; end if;
  -- access, consistency of nature × subcategory, history and audit of this movement
  v_n := cw_prod.transaction_classify(p_txn, p_nature, p_subcategory, false);
  if p_scope = 'ONE' then return v_n; end if;
  select * into t from cw_prod.transactions where id = p_txn;
  v_key := cw_prod_private.recurrence_key(t.merchant_norm);
  if t.merchant_norm = 'SEM DESCRICAO' or length(v_key) < 2 then return v_n; end if;
  insert into cw_prod.transaction_rules (scope, client_id, pattern, direction, nature, subcategory, priority, created_by)
  values ('CLIENT', t.client_id, left(v_key, 80), t.direction::text, p_nature::cw_prod.txn_nature, p_subcategory, 1000, auth.uid())
  on conflict (client_id, pattern, direction) where scope = 'CLIENT'
  do update set nature = excluded.nature, subcategory = excluded.subcategory, active = true
  returning id into v_rule;
  for r in select id from cw_prod.transactions
            where client_id = t.client_id and direction = t.direction and id <> p_txn
              and classification_source <> 'MANUAL' and review_status <> 'IGNORED'
              and (p_scope = 'ALL' or review_status = 'NEEDS_REVIEW')
              and cw_prod_private.recurrence_key(merchant_norm) = v_key
            for update loop
    update cw_prod.transactions set nature = p_nature::cw_prod.txn_nature, subcategory = p_subcategory,
           classification_source = 'CLIENT_RULE', rule_id = v_rule,
           confidence = (case when p_nature = 'TRANSFER' and transfer_pair_id is null then 'MEDIUM' else 'HIGH' end)::cw_prod.txn_confidence,
           review_status = 'AUTO',
           transfer_pair_id = case when p_nature = 'TRANSFER' then transfer_pair_id end,
           reimbursement_of_id = case when p_nature = 'ADJUSTMENT' then reimbursement_of_id end
     where id = r.id;
    perform cw_prod_private.record_decision(r.id);
    v_n := v_n + 1;
  end loop;
  if p_nature = 'TRANSFER' then perform cw_prod_private.pair_transfers(t.client_id); end if;
  perform cw_prod_private.write_audit('RECLASSIFY', 'transaction_rules', v_rule::text, t.client_id, null,
    jsonb_build_object('scope', p_scope, 'nature', p_nature, 'subcategory', p_subcategory, 'affected', v_n));
  return v_n;
end $$;

revoke all on function cw_prod_private.merchant_key(text), cw_prod_private.recurrence_key(text) from public, anon, authenticated;
revoke all on function cw_prod.transaction_classify_scope(uuid, text, text, text) from public, anon;
grant execute on function cw_prod.transaction_classify_scope(uuid, text, text, text) to authenticated;

